import { breakpoints } from 'app/theme/foundation';
import { DRAWER_HEADER_ROW_HEIGHT } from 'app/theme/components/zimmDrawerShared';

// Figma's actual named drawer sizes (SFCC-898) — five named sizes, not the three/four this
// file previously guessed at. Each name below matches Figma's own naming exactly, so there's
// no re-deriving which number belongs to which concept next time this file is touched:
//
//   Desktop Large — 50%  — Product Details, Filters (desktop width)
//   Tablet        — 80%  — Product Details, Filters (tablet width)
//   Desktop Small — 25%  — Notify Me, Wishlist, Find in Boutique, Regional Storefront,
//                           Cookies, Login
//   X-Large       — 82%  — Cart (not yet built as a drawer — see the `xLarge` variant below)
//   Mobile        — unchanged, the baseStyle treatment every variant collapses to below `md`.
//
// An earlier revision of this file measured 82% off a Figma frame annotated "Tablet = 82% of
// screen" and used it as `small`'s (now `tablet`'s) value — that frame's annotation was wrong
// (or superseded): 82% is actually X-Large's value (Cart), a completely different drawer this
// codebase hasn't built yet, and Tablet is genuinely 80%. Corrected once confirmed directly
// against the list above, not another single frame's own label.
const WIDTH_LARGE = '50%';
const WIDTH_TABLET = '80%';
// The original width set when this drawer shell was first built (2026-08-27) — matches Figma's
// "Desktop Small" exactly. Used by every viewport-independent narrow utility drawer (Find in
// Boutique today; Notify Me/Wishlist/Regional Storefront/Cookies/Login once those exist).
const WIDTH_SMALL = '25%';
// Cart isn't built as a drawer yet (confirmed: it's a full page today) — this constant and the
// `xLarge` variant below exist so the real Figma value is already in place, under the right
// name, whenever that work starts, rather than needing this same "which number is this?"
// investigation again.
const WIDTH_XLARGE = '82%';

// Mobile deliberately leaves a strip of backdrop visible below the panel (SFCC-736 AC 9,
// PO-approved 2026-08-21 — "so a user can easily navigate out"). Re-measured against node
// 40002218:42903 (SFCC-898): overlay 956px tall, panel 898px tall — exactly 58px. No named
// spacing scale step lands on 58px, so this is a provisional raw value pending a foundation
// token, same as the other pending constants in this file.
const MOBILE_BOTTOM_GAP = '3.625rem'; // 58px

// Close-button inset, measured from the pdp/drawer header frames. `tablet`/`small`/`xLarge`/
// `mobile` all share the same measured inset (32px/40px) at every width — only `large` switches
// to the wider 48px/64px inset, at/above the tablet breakpoint. Below that breakpoint `large`'s
// own override doesn't apply either, and the baseStyle inset is used instead, which is also how
// the whole drawer collapses to the mobile treatment on a narrow viewport regardless of `size`.
const INSET_COMPACT = { top: 'var(--zimm-scale-3xl)', right: 'var(--zimm-scale-2xl)' };
const INSET_LARGE = { top: 'var(--zimm-scale-1200)', right: 'var(--zimm-scale-4xl)' };

// Header constants — from Figma drawer/header frame measurements.
// Compact horizontal inset (small/mobile): px=32px. Large desktop: px=64px.
// Small desktop header uses py=24px. Large desktop: container height=120px (row centred).
// Mobile base: container height=72px.
const HEADER_PADDING_COMPACT_X = 'var(--zimm-scale-2xl)'; // 32px
const HEADER_PADDING_LARGE_X = 'var(--zimm-scale-4xl)'; // 64px
const HEADER_PADDING_Y = 'var(--zimm-scale-xl)'; // 24px — small desktop py
// audit-allow: Figma-confirmed container heights with no --zimm-scale equivalents at these values.
const HEADER_HEIGHT_LARGE = '120px';
const HEADER_HEIGHT_MOBILE = '72px';

export const ZimmDrawer = {
  parts: ['overlay', 'content', 'closeButton', 'header', 'headerTitle'],
  baseStyle: {
    // Explicit position/inset rather than relying on Chakra's own built-in `Drawer` overlay
    // styling — confirmed via inspection that it doesn't apply (renders `position: static`,
    // zero size) when the `<Drawer>` isn't given Chakra's own `size` prop, which this component
    // deliberately omits (see maxWidth note below). Owning it here avoids depending on that.
    overlay: {
      position: 'fixed',
      inset: 0,
      background: 'var(--zimm-color-opacity-50)',
      zIndex: 'overlay',
    },
    content: {
      // Chakra's own <DrawerContent> baked in a default white background
      // (@chakra-ui/theme's modal.js `baseStyleDialog`: `bg: colors.white`) that this recipe
      // never needed to set itself while that component was still in use — now that
      // ZimmDrawer hand-rolls its own content element (see index.tsx's file-level comment),
      // nothing supplies one unless it's set here. Matches Figma's pdp/drawer panel background
      // (bg-[var(--brand/color/palette/white,white)]) — --zimm-color-bg-07 resolves to the
      // same grey.white value (SFCC-898 — the panel briefly had no background at all).
      background: 'var(--zimm-color-bg-07)',
      width: '100%',
      // Matches `width` at every step below — Chakra's own `Drawer` theme defaults to
      // `size="xs"` (maxW 20rem) when no `size` prop is passed to `<Drawer>` (deliberate: its
      // fixed size scale has no 50%/25% steps), and that default `maxW` otherwise still caps
      // our own `width` override since we never reset it.
      maxWidth: '100%',
      // Mobile positioning: override index.tsx's hardcoded `right: 0` to allow `left: 0; width: 100%`
      // full-width layout. With both `left: 0; right: 0;` on mobile, the drawer stretches
      // properly from edge to edge. Without this override, `right: 0; width: 100%` alone (on
      // position:fixed) spans from -100% (off left) to 0 (right), causing the pale left stripe.
      // Audited 2026-09-16 — contentStyles spread AFTER the hardcoded props in index.tsx,
      // so these overrides take effect.
      left: 0,
      right: 'auto',
      // A `height` reduction, not a `bottom` offset — Chakra's own Slide transition (see
      // @chakra-ui/transition's slide.js `placement: 'right'` case) pins the sliding wrapper
      // with `position: fixed; top: 0; right: 0; bottom: 0`, a definite height. `bottom` on
      // this `position: relative` DrawerContent just shifts the box within that instead of
      // reliably opening a gap (SFCC-898 — mobile bottom gap wasn't rendering at all); a
      // percentage `height` resolves cleanly against that definite-height ancestor instead.
      height: `calc(100% - ${MOBILE_BOTTOM_GAP})`,
      // Header stays fixed; only the content area (ZimmPdpDrawer's own `content` part) scrolls —
      // AC 10, "content area scrolls independently without the tab header scrolling".
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
    },
    // Was missing `position: absolute` since this component's original commit — the
    // top/right insets below were silently no-ops (closeButton rendered as a normal in-flow
    // block instead of overlaying the header's corner), which is the root cause of SFCC-898's
    // close-button-misaligned-with-tabs defect across every breakpoint.
    //
    // height/display/alignItems/justifyContent: matches zimmTabs.css.ts's `menu.minHeight`
    // (DRAWER_HEADER_ROW_HEIGHT, zimmDrawerShared.ts) and centers the icon inside it — the
    // close icon's own intrinsic size doesn't equal the tab row's real rendered height, so
    // matching only `top` between the two (as before) left their vertical centers slightly
    // offset (SFCC-898, mobile). Only applies to the floating close button (no `title` passed) —
    // the inline title-row close button below is a normal flex child, not absolutely positioned.
    closeButton: {
      position: 'absolute',
      ...INSET_COMPACT,
      height: DRAWER_HEADER_ROW_HEIGHT,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    // Drawer header — title (flex-1, left) + close button (right).
    // baseStyle applies the mobile/compact treatment: px=32px, container h=72px centred.
    header: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-xs)',
      backgroundColor: 'var(--zimm-color-text-inverse)',
      paddingInline: HEADER_PADDING_COMPACT_X,
      paddingBlock: 0,
      minHeight: HEADER_HEIGHT_MOBILE,
      flexShrink: 0,
    },
    headerTitle: {
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      whiteSpace: 'nowrap',
    },
  },
  variants: {
    large: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_LARGE,
          maxWidth: WIDTH_LARGE,
          height: '100%',
          // Override baseStyle's mobile `left: 0; right: 'auto'` to restore right-aligned positioning.
          left: 'auto',
          right: 0,
        },
      },
      closeButton: {
        [`@media (min-width: ${breakpoints.md})`]: INSET_LARGE,
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          paddingInline: HEADER_PADDING_LARGE_X,
          minHeight: HEADER_HEIGHT_LARGE,
        },
      },
    },
    // Figma's "Tablet" size — the tablet-range step for Product Details/Filters, which
    // graduates to `large` (Desktop Large) at the desktop breakpoint via the caller's own
    // useBreakpointValue (ZimmPdpDrawer never selects this variant itself).
    tablet: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_TABLET,
          maxWidth: WIDTH_TABLET,
          height: '100%',
          left: 'auto',
          right: 0,
        },
      },
    },
    // Figma's "Desktop Small" — always narrow, at every width above the mobile collapse. No
    // js-level graduation to another variant the way `tablet` graduates to `large` — this is
    // the whole point for its utility-drawer consumers (Find in Boutique today).
    small: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_SMALL,
          maxWidth: WIDTH_SMALL,
          height: '100%',
          left: 'auto',
          right: 0,
        },
      },
    },
    // Figma's "X-Large" (Cart) — not consumed anywhere yet (Cart is a full page today, not a
    // drawer), but the real value is already here under the right name for when that changes.
    xLarge: {
      content: {
        [`@media (min-width: ${breakpoints.md})`]: {
          width: WIDTH_XLARGE,
          maxWidth: WIDTH_XLARGE,
          height: '100%',
          left: 'auto',
          right: 0,
        },
      },
      header: {
        [`@media (min-width: ${breakpoints.md})`]: {
          minHeight: 'unset',
          paddingBlock: HEADER_PADDING_Y,
        },
      },
    },
    // No override — the baseStyle above already is the mobile treatment.
    mobile: {},
  },
};

1	import React, { useEffect, useId } from 'react';
2	import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
3	import type { SystemStyleObject } from '@chakra-ui/react';
4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	import { useUiCopy } from 'app/hooks/useUiCopy';
7	
8	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
9	
10	// Shared scroll-lock state — multiple ZimmDrawer instances can be open simultaneously (e.g. a
11	// nested utility drawer over a PDP drawer). Each open instance increments this counter; only
12	// the final cleanup (count back to 0) restores the original overflow value, preventing an
13	// earlier-closing drawer from unlocking the body while a second drawer is still open.
14	let scrollLockCount = 0;
15	let scrollLockPrev = '';
16	
17	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
18	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
19	// which satisfies it, hence the explicit cast.
20	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
21	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
22	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
23	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
24	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
25	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
26	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
27	
28	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
29	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
30	// variants) and forwards everything else straight to the wrapped component, so `transition`
31	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
32	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
33	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
34	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
35	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
36	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
37	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
38	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
39	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
40	const MotionChakraDiv = motion(chakra.div);
41	
42	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
43	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
44	// page today, not a drawer).
45	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile' | 'prompt';
46	
47	type ZimmDrawerBaseProps = {
48	  /** Whether the drawer is open. */
49	  isOpen: boolean;
50	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
51	  onClose: () => void;
52	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
53	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
54	  size: ZimmDrawerSize;
55	  children: React.ReactNode;
56	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
57	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
58	   *  is provided. */
59	  titleStyle?: 'large' | 'small';
60	  /** Element to focus when the drawer closes. Use when the trigger may not have received
61	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
62	   *  document.body and AC10 focus-return fails. */
63	  finalFocusRef?: React.RefObject<HTMLElement>;
64	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
65	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
66	  initialFocusRef?: React.RefObject<HTMLElement>;
67	};
68	
69	/**
70	 * Exactly one of:
71	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
72	 *                   accessible name is derived from the rendered title element automatically.
73	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
74	 *                   tab header). Paired with the floating close button by default. Pass
75	 *                   `boxedHeader` alongside it when the drawer has no header content of its own
76	 *                   to supply (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body)
77	 *                   but still wants the close button in the same in-flow header row `title` gets,
78	 *                   instead of floating over the content — the title `<span>` renders with no
79	 *                   text, purely to hold the close button's usual right-aligned position. The
80	 *                   drawer's accessible name still comes from `labelledBy`, unaffected.
81	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
82	 *                   is available.
83	 */
84	type ZimmDrawerProps = ZimmDrawerBaseProps &
85	  (
86	    | { title: string; labelledBy?: never; 'aria-label'?: never; boxedHeader?: never }
87	    | { title?: never; labelledBy: string; 'aria-label'?: never; boxedHeader?: boolean }
88	    | { title?: never; labelledBy?: never; 'aria-label': string; boxedHeader?: never }
89	  );
90	
91	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
92	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
93	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
94	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
95	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
96	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
97	type ZimmDrawerContentConfig = {
98	  children: React.ReactNode;
99	  onClose: () => void;
100	  /** Renders an inline header row (title left, close button right) instead of the floating
101	   *  close button when provided — see ZimmDrawerProps' `title` member. */
102	  title?: string;
103	  titleId?: string;
104	  titleStyle?: 'large' | 'small';
105	  labelledBy?: string;
106	  ariaLabel?: string;
107	  /** Forces the same in-flow header row `title` renders (empty title span, close button in its
108	   *  usual right-aligned slot) instead of the floating close button — see ZimmDrawerProps'
109	   *  `labelledBy` member. Meaningless without `labelledBy`. */
110	  boxedHeader?: boolean;
111	  contentStyles: SystemStyleObject;
112	  headerStyles: SystemStyleObject;
113	  headerTitleStyles: SystemStyleObject;
114	  closeButtonStyles: SystemStyleObject;
115	  /** SFCC-831/689 rework — the boxed close button's own row (title/boxedHeader branch only),
116	   *  giving it a real 44px height to measure `header`'s paddingBlock-driven variants against.
117	   *  See zimmDrawer.css.ts's `headerCloseButton` for why the floating branch below doesn't
118	   *  need this (its own `closeButtonStyles` already sets an explicit height). */
119	  headerCloseButtonStyles: SystemStyleObject;
120	};
121	
122	/**
123	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
124	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
125	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
126	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
127	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
128	 *
129	 * Renders the inline header row (title left — empty when there's no `title` text — close button
130	 * right) when either `title` or `boxedHeader` is passed, or a floating close button only when
131	 * neither is — see ZimmDrawer's own docblock for when each is used.
132	 *
133	 * @param props see ZimmDrawerContentConfig
134	 */
135	const ZimmDrawerContent = ({
136	  children,
137	  onClose,
138	  title,
139	  titleId,
140	  titleStyle = 'large',
141	  labelledBy,
142	  ariaLabel,
143	  boxedHeader,
144	  contentStyles,
145	  headerStyles,
146	  headerTitleStyles,
147	  closeButtonStyles,
148	  headerCloseButtonStyles,
149	}: ZimmDrawerContentConfig) => {
150	  const { t } = useUiCopy();
151	  const { getDialogProps, getDialogContainerProps } = useModalContext();
152	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
153	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
154	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
155	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
156	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
157	  if (title && titleId) {
158	    dialogProps['aria-labelledby'] = titleId;
159	  } else if (labelledBy) {
160	    dialogProps['aria-labelledby'] = labelledBy;
161	  }
162	  const containerProps = getDialogContainerProps();
163	
164	  return (
165	    <ModalFocusScope>
166	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
167	        <MotionChakraDiv
168	          {...dialogProps}
169	          initial={{ x: '100%' }}
170	          animate={{ x: 0 }}
171	          exit={{ x: '100%' }}
